function PingServer_ApiCall() {
    jQuery.post(base_url + 'concerto-json/PingServer_ApiCall', {
        ajax: true,
        version: new Date().toISOString().split('T')[0]
    }).done(function(result) {
        console.log('Server Pinged');
    }).fail(function(jqXHR, textStatus, errorThrown) {
        console.error('API Call failed:', textStatus, errorThrown);
    });
}


function ValidateFormSubmit_JTC(formclass, label = '') {
    jQuery(document).off().on("submit", "." + formclass, function(e) {
        e.preventDefault();
        var ajax_save_form = jQuery(this);
        var formaction = ajax_save_form.attr('data-action');
        var getcontroller = ajax_save_form.attr('data-controller');
        if (typeof getcontroller !== 'undefined' && getcontroller !== false) {
            var ActionController = ajax_save_form.attr('data-controller');
        } else {
            var ActionController = controller;
        }
        jQuery.ajax({
            enctype: 'multipart/form-data',
            url: base_url + ActionController + '/' + formaction,
            data: new FormData(this),
            method: 'post',
            dataType: 'json',
            processData: false,
            contentType: false,
            cache: false,
            timeout: 600000,
            secure: true,
            crossDomain: true,
            headers: {
                'Access-Control-Allow-Origin': '*',
            },
            beforeSend: function() {
                showloader(1);
                //jQuery('.liquiditydataload').html('<img class="commom-preloader-resultTable uk-first-column" src="' + base_url + 'assets/dash/images/dorey-tool-admin-loader.gif" style="margin: auto;"></img>');
                ajax_save_form.find(":submit").prop('disabled', true);
                ajax_save_form.find(":submit").html('Processing...');
            },
            success: function(response) {
                showloader(0);
                ajax_save_form.find(":submit").prop('disabled', false);
                ajax_save_form.find(":submit").html(label);
                if (response.status) {
                    if (response.openSuccessPopup) {
                        openSuccessPopup(response.message, response.http_redirect);
                    } else {
                        window.location.href = response.http_redirect;
                    }
                } else {
                    openErrorPopup(response.message, response.title);
                }
            }
        });
    });
}

function openErrorPopup(error, detaultTitle) {
    document.getElementById('error-messageError').innerHTML = error;
    jQuery('.defaultmodaltypetitlemsgError').text(detaultTitle);
    UIkit.modal('#modal-sectionswithErrorPopup').show();
}

function openSuccessPopup(message, http_redirect) {
    let StrToCheck = "liquidity";
    let StrToChecknew = "contributions";
    let detaultTitle = 'Error';
    if (message.indexOf(StrToCheck) != -1 || message.indexOf(StrToChecknew) != -1) {
        detaultTitle = 'Check';
    }
    document.getElementById('error-messageConfirm').innerText = message;
    jQuery('.defaultmodaltypetitlemsgConfirm').text(detaultTitle);
    const okButton = document.getElementById('ok-button');
    okButton.addEventListener('click', () => window.location.href = http_redirect);

    UIkit.modal('#modal-confirmationsuccesspopup').show();
}

